"""Los lanzadores del CLI: web, desktop, serve, mcp y schema.(Parte del paquete `cli`; la fachada está en `events_core.cli`.)Original: CLI `eui`: lo que un agente usa en vez de la API cruda.Comandos: `doctor` (la puerta), `config`, y la lectura `repo`, `item` y`schema`, todos sobre el mismo cliente HTTP. La migración llega después.Los dos clientes se abren con `--webapp` (la web en el navegador) y`--desktop`; si no están instalados, el CLI ofrece instalarlos.    uv run --directory services/core python -m events_core.cli doctor    uv run --directory services/core python -m events_core.cli config --jsonCódigos de salida: 0 bien, 1 algo no cuadra, 2 uso o valor inválido (argparsesale con 2 por su cuenta)."""from __future__ import annotationsimport argparseimport jsonimport osimport sysimport timefrom urllib.error import HTTPError, URLErrorfrom urllib.request import urlopenfrom .. import config as configuracionfrom .. import migracionfrom .cliente import TIMEOUT_Sfrom .comun import _contexto, _fallofrom .escritorio import (    _SIN_CONSOLA,    RELEASES,    _abrir,    _confirmar,    _desktop_instalado,    _dist_de_la_webapp,    _instalar_desktop,)from .http import _get, _postdef _web(args: argparse.Namespace) -> int:    """Enciende el core si no responde, y abre la web servida por él.    El core se lanza como proceso aparte con `EUI_IDLE_MINUTES`, así se apaga solo    cuando nadie lo usa. Si ya responde (otra app o un `eui web` anterior), se le    añade la web instalada en caliente (`POST /webapp`) y se comprueba que la    sirve. El binario es el de la máquina si el envoltorio lo encontró    (`EUI_CORE_BIN`: el `events-core` que publicó el desktop, sin consola); si    no, `eui` se sirve a sí mismo, y en desarrollo se usa    `python -m events_core.serve`.    """    import subprocess  # noqa: PLC0415    import webbrowser  # noqa: PLC0415    puerto = args.port or configuracion.leer_segura().port    url = f"http://127.0.0.1:{puerto}"    dist_texto = os.environ.get("EUI_WEB_DIST", "").strip()    if not dist_texto:        encontrado = _dist_de_la_webapp()        dist_texto = str(encontrado) if encontrado else ""    datos, _, _ = _get(f"{url}/health")    if datos is None:        # Sin las `_PYI_*`: el hijo reutilizaría la carpeta temporal del padre        # (onefile) y moriría cuando el padre la borre al salir.        entorno = {            **{k: v for k, v in os.environ.items() if not k.startswith("_PYI_")},            "EUI_PORT": str(puerto),            "EUI_IDLE_MINUTES": str(args.idle_minutes),        }        if dist_texto:            entorno["EUI_WEB_DIST"] = dist_texto        # El core de la máquina si el envoltorio encontró uno (el del desktop,        # que no trae CLI); si no, `eui` se sirve a sí mismo (`eui serve`), y        # en desarrollo se arranca el módulo.        core_compartido = os.environ.get("EUI_CORE_BIN", "").strip()        if core_compartido:            orden = [core_compartido]        elif getattr(sys, "frozen", False):            orden = [sys.executable, "serve"]        else:            orden = [sys.executable, "-m", "events_core.serve"]        # Sin heredar la terminal: `eui web` ya volvió y uvicorn escribiría sus        # líneas encima del prompt. Lo útil del core va al registro (SQLite).        subprocess.Popen(            orden,            env=entorno,            stdin=subprocess.DEVNULL,            stdout=subprocess.DEVNULL,            stderr=subprocess.DEVNULL,            creationflags=_SIN_CONSOLA,        )        limite = time.monotonic() + 15        while time.monotonic() < limite:            datos, _, _ = _get(f"{url}/health")            if datos is not None:                break            time.sleep(0.25)        if datos is None:            print(f"El core no respondió en {url}. Revisa el registro de eventos.", file=sys.stderr)            return 1    if dist_texto:        _, detalle_web, estado_web = _post(f"{url}/webapp", {"dist": dist_texto})        if estado_web == 404:            print(                f"El core que ya está en {url} no sabe montar la web en caliente "                "(es anterior). Ciérralo y vuelve a lanzar `eui web`.",                file=sys.stderr,            )            return 1        if estado_web != 200:            problema = detalle_web or f"HTTP {estado_web}"            print(f"No pude montar la web en {url}: {problema}", file=sys.stderr)            return 1    print(f"Core en {url} (se apaga tras {args.idle_minutes:g} min sin uso)")    if not args.no_open:        if _estado(f"{url}/") != 200:            print(                f"El core en {url} no sirve la web app; revisa el `dist` o reinícialo.",                file=sys.stderr,            )            return 1        webbrowser.open(url)    return 0def _estado(url: str) -> int:    """Código HTTP de un GET aunque la respuesta no sea JSON; 0 sin respuesta."""    try:        with urlopen(url, timeout=TIMEOUT_S) as respuesta:  # noqa: S310            return int(respuesta.status)    except HTTPError as exc:        return exc.code    except (URLError, OSError):        return 0def _desktop(args: argparse.Namespace) -> int:    """`eui --desktop`: abre el desktop, instalándolo si falta."""    ruta = _desktop_instalado()    if ruta is not None:        _abrir(ruta)        return 0    print("No tienes instalado el desktop de Events UI.")    sistema = {"nt": "Windows", "darwin": "macOS"}.get(os.name, "Linux")    if not _confirmar(f"¿Descargar e instalar el instalador de {sistema}? [s/N] "):        print(f"Instaladores: {RELEASES}/latest", file=sys.stderr)        return 1    return _instalar_desktop()def _serve(args: argparse.Namespace) -> int:    """El core en primer plano (`eui serve`), que es el modo que usa `eui web`.    Los imports son explícitos porque PyInstaller solo empaqueta lo que ve: el    `uvicorn.run("events_core.main:app")` de `serve` llega por cadena.    """    # El entorno va antes de importar: `serve.PORT` se calcula al importarse.    if args.port:        os.environ["EUI_PORT"] = str(args.port)    if args.idle_minutes is not None:        os.environ["EUI_IDLE_MINUTES"] = str(args.idle_minutes)    from . import main as _app  # noqa: F401, PLC0415    from . import serve  # noqa: PLC0415    return serve.main()def _mcp(args: argparse.Namespace) -> int:    # Import perezoso: el CLI normal no carga el servidor ni su protocolo.    from .mcp_servidor import permite_escritura, servir    return servir(permitir_escritura=permite_escritura(args.permitir_escritura))def _schema(args: argparse.Namespace) -> int:    if args.tema == "puertas":        # El esquema del archivo es local: no hace falta core ni raíz.        from ..items.modelo.puertas import ESQUEMA_PUERTAS        print(json.dumps(ESQUEMA_PUERTAS, indent=2 if args.pretty else None))        return 0    if args.tema == "migrate":        # El esquema del plan es local: no hace falta core ni raíz.        print(json.dumps(migracion.ESQUEMA_PLAN, indent=2 if args.pretty else None))        return 0    _, url = _contexto(args)    datos, detalle, estado = _get(f"{url}/openapi.json")    if detalle:        return _fallo(detalle, estado)    print(json.dumps(datos, indent=2 if args.pretty else None))    return 0